with metrics as (select id, txn_type, amount, txn_time, merchant, is_flagged, min(amount) over (partition by account_id) as account_id_min_amount, last_value(merchant, true) over w_recent as last_known_merchant from transactions window w_recent as (partition by to_date(txn_time) order by amount asc, id asc rows between unbounded preceding and current row)) select id, amount, txn_time, merchant, account_id_min_amount from metrics order by merchant desc, txn_time asc;
